import{_ as t}from"./chunks/pilotage.FGz03KRv.js";import{_ as a}from"./chunks/coupe.64JYIVTF.js";import{_ as r,o as s,c as n,a2 as o}from"./chunks/framework.CQxpk36T.js";const b=JSON.parse(`{"title":"Visite de l'interface","description":"","frontmatter":{},"headers":[],"relativePath":"interface.md","filePath":"interface.md","lastUpdated":1793572677000}`),l={name:"interface.md"};function i(u,e,d,c,p,g){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="visite-de-l-interface" tabindex="-1">Visite de l&#39;interface <a class="header-anchor" href="#visite-de-l-interface" aria-label="Permalink to &quot;Visite de l&#39;interface&quot;">​</a></h1><p>L&#39;interface tient sur un téléphone tenu à une main, et s&#39;étale sur une tablette ou un ordinateur. Elle a trois onglets : <strong>Maison</strong>, <strong>Tableau</strong> et <strong>Énergie</strong>, en bas de l&#39;écran sur téléphone, en haut sur ordinateur.</p><h2 id="la-barre-du-haut" tabindex="-1">La barre du haut <a class="header-anchor" href="#la-barre-du-haut" aria-label="Permalink to &quot;La barre du haut&quot;">​</a></h2><figure class="haven-shot"><img src="'+t+'" alt="La maison sélectionnée, avec la barre du haut et le panneau des pièces"><figcaption><strong>Barre du haut</strong> : nom de la propriété, heure, météo et présences à gauche ; étiquettes, éditeur et réglages à droite.</figcaption></figure><p>À gauche :</p><ul><li>le <strong>nom de la propriété</strong> ;</li><li>l&#39;<strong>heure</strong> de la scène : un toucher ouvre le <a href="#l-heure-et-la-meteo">réglage de l&#39;heure</a> ;</li><li>la <strong>météo</strong> et la température : un toucher ouvre le détail ;</li><li>une <strong>initiale par personne à la maison</strong> (entités <code>person.*</code> de Home Assistant).</li></ul><p>À droite, sur l&#39;onglet Maison :</p><ul><li>l&#39;<strong>étiquette</strong> affiche ou masque les étiquettes flottantes au-dessus des pièces ;</li><li>le <strong>crayon</strong> ouvre l&#39;<a href="/HAven-docs/guide/editeur">éditeur de la page</a> ;</li><li>la <strong>pastille</strong> ouvre les <a href="#les-reglages">réglages</a>. Sa couleur dit l&#39;état de la connexion : Démo, Home Assistant, Connexion… ou Hors ligne.</li></ul><h2 id="l-onglet-maison" tabindex="-1">L&#39;onglet Maison <a class="header-anchor" href="#l-onglet-maison" aria-label="Permalink to &quot;L&#39;onglet Maison&quot;">​</a></h2><p>La vue 3D. Un doigt fait tourner la maquette, deux doigts zooment et la déplacent (à la souris : glisser pour tourner, molette pour zoomer vers le pointeur, clic droit pour déplacer).</p><ul><li><strong>Rien de sélectionné</strong> : un résumé liste les bâtiments avec le nombre de pièces allumées, la production solaire et les voitures (garées ou absentes). Toucher une ligne sélectionne le bâtiment. Le bouton <strong>Vue d&#39;ensemble</strong> recadre toute la propriété.</li><li><strong>Un bâtiment touché</strong> : la caméra s&#39;en approche, les autres bâtiments s&#39;estompent, et son <strong>panneau</strong> s&#39;ouvre avec ses pièces, étage par étage : lumières, températures, chauffage, volets, portes, véhicules, panneaux solaires.</li><li><strong>Une pièce touchée</strong> (sur la maquette, dans le panneau ou sur son étiquette) : tout s&#39;éteint si une de ses lampes est allumée, tout s&#39;allume sinon.</li></ul><h3 id="la-vue-en-coupe" tabindex="-1">La vue en coupe <a class="header-anchor" href="#la-vue-en-coupe" aria-label="Permalink to &quot;La vue en coupe&quot;">​</a></h3><p>Quand le bâtiment a des <a href="/HAven-docs/guide/plans">plans intérieurs</a>, son panneau propose <strong>Extérieur / RDC / Étage</strong>. Le toit s&#39;efface, l&#39;étage choisi apparaît en maison de poupée, meublé ; les sols se teintent selon la température de chaque pièce (bleuté sous 20 °C, orangé au-dessus de 21 °C) et une petite flamme signale le chauffage qui tourne. Les pièces restent dans la pénombre d&#39;un intérieur ; une pièce allumée est baignée par la lumière chaude de son plafonnier, plus forte sous la lampe et douce vers les coins, qui éclaire aussi ses murs et ses meubles. Toucher une pièce allume ou éteint ses lumières.</p><p><img src="'+a+'" alt="Vue en coupe du rez-de-chaussée"></p><h2 id="les-onglets-tableau-et-energie" tabindex="-1">Les onglets Tableau et Énergie <a class="header-anchor" href="#les-onglets-tableau-et-energie" aria-label="Permalink to &quot;Les onglets Tableau et Énergie&quot;">​</a></h2><ul><li><strong><a href="/HAven-docs/home-assistant/tableau">Tableau</a></strong> : une tuile par appareil, rangées par bâtiment puis par pièce, avec scènes, favoris et recherche.</li><li><strong><a href="/HAven-docs/home-assistant/energie">Énergie</a></strong> : flux en direct, bilan et courbe de la journée, batterie, voiture électrique et appareils qui consomment.</li></ul><h2 id="l-heure-et-la-meteo" tabindex="-1">L&#39;heure et la météo <a class="header-anchor" href="#l-heure-et-la-meteo" aria-label="Permalink to &quot;L&#39;heure et la météo&quot;">​</a></h2><p>Le <strong>réglage de l&#39;heure</strong> fait défiler la journée (bouton lecture) ou choisit une heure et un jour précis : le soleil, la lune, les ombres et la saison suivent. L&#39;heure simulée s&#39;affiche en couleur dans la barre ; <strong>Maintenant</strong> revient à l&#39;heure réelle.</p><p>La <strong>météo</strong> vient d&#39;<a href="https://open-meteo.com" target="_blank" rel="noreferrer">Open-Meteo</a> : gratuit, sans clé, relevée toutes les 10 minutes. La position envoyée est arrondie à environ 1 km. Sans accès à Internet, HAven prend la première entité <code>weather.*</code> de Home Assistant.</p><p>Après le coucher du soleil, l&#39;interface s&#39;assombrit d&#39;elle-même pour ne pas éblouir.</p><h2 id="les-reglages" tabindex="-1">Les réglages <a class="header-anchor" href="#les-reglages" aria-label="Permalink to &quot;Les réglages&quot;">​</a></h2><p>La pastille en haut à droite ouvre les réglages :</p><table tabindex="0"><thead><tr><th>Réglage</th><th>Rôle</th></tr></thead><tbody><tr><td>Adresse de Home Assistant</td><td><strong>Se connecter</strong> à Home Assistant, ou <strong>Rester en démo</strong> (<a href="/HAven-docs/home-assistant/">détails</a>)</td></tr><tr><td>Météo</td><td>En direct, ou un temps type en mode démo</td></tr><tr><td>Propriété</td><td><strong>Éditer</strong> la propriété, ou <strong>Relever une position</strong> pour décrire portes et fenêtres</td></tr><tr><td>Qualité graphique</td><td>Auto, Haute, Moyenne ou Économe</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Qualité graphique</p><p><strong>Auto</strong> mesure le temps que met chaque image et ajuste la définition et les effets. Les effets de post-traitement (halo, contour, flou de maquette) ne sont actifs qu&#39;en qualité haute. <strong>Économe</strong> ménage la batterie d&#39;un vieux téléphone ou d&#39;une tablette murale.</p></div><h2 id="installer-sur-l-ecran-d-accueil" tabindex="-1">Installer sur l&#39;écran d&#39;accueil <a class="header-anchor" href="#installer-sur-l-ecran-d-accueil" aria-label="Permalink to &quot;Installer sur l&#39;écran d&#39;accueil&quot;">​</a></h2><p>HAven est une application web installable :</p><ul><li><strong>iPhone, iPad</strong> : Safari → Partager → « Sur l&#39;écran d&#39;accueil » ;</li><li><strong>Android</strong> : Chrome → menu → « Installer l&#39;application » ;</li><li><strong>Ordinateur</strong> : l&#39;icône d&#39;installation dans la barre d&#39;adresse de Chrome ou Edge.</li></ul><p>Elle s&#39;ouvre alors en plein écran, sans barre de navigateur. Pour l&#39;ouverture instantanée hors ligne, il faut la servir en HTTPS : voir <a href="/HAven-docs/hebergement#https">Héberger</a>.</p>',28)])])}const v=r(l,[["render",i]]);export{b as __pageData,v as default};
